// The Worker entry: sends store sub-domains (<name>.shopilier.com) to their websites, then hands every request to
// the Next.js app that `opennextjs-cloudflare build` bundles into .open-next/worker.js. See src/lib/store-host.ts.
// @ts-ignore: generated by the build
import nextApp from "./.open-next/worker.js";
import { storeHost } from "./src/lib/store-host";

type Env = { STORE_DOMAIN?: string };

export default {
  async fetch(request: Request, env: Env, ctx: unknown) {
    const url = new URL(request.url);
    const action = storeHost(url.hostname, url.pathname, url.search, env.STORE_DOMAIN || "");
    if (action.kind === "redirect") {
      return new Response(null, { status: 301, headers: { Location: action.to, "Cache-Control": "no-store" } });
    }
    if (action.kind === "rewrite") {
      url.pathname = action.path;
      request = new Request(url, request);
    }
    return nextApp.fetch(request, env, ctx);
  },
};
